class Dispatcher {
    private val handlers =
        mutableMapOf<KClass<out DomainEvent>, MutableList<(DomainEvent) -> Unit>>()
    fun <T : DomainEvent> on(type: KClass<T>, h: (T) -> Unit) =
        handlers.getOrPut(type) { mutableListOf() }.add { h(it as T) }
    fun publish(e: DomainEvent) = handlers[e::class]?.forEach { it(e) }
}
